/// `UnsettlingLamp.before_power_amount_changed` — capture phase. On
/// the first eligible debuff application (player → enemy) this combat,
/// flip the relic from `ARMED` to `CAPTURED` so the modify-given arm
/// starts doubling. Per C# canon
/// `UnsettlingLamp.cs::BeforePowerAmountChanged`. Bead `sts2-rs-7uo4`.
pub(crate) fn on_before_power_amount_changed_unsettling_lamp(
    state: &mut CombatState,
    ctx: &crate::hooks::PowerAmountCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::UnsettlingLamp) {
        return EffectResult::NotImplemented;
    }
    if unsettling_lamp_state(state) != Some(UNSETTLING_LAMP_ARMED) {
        return EffectResult::NotImplemented;
    }
    if !unsettling_lamp_eligible(ctx) {
        return EffectResult::NotImplemented;
    }
    // v0.111.0 adds `if (target.HasPower<ArtifactPower>()) return;`
    // (`UnsettlingLamp.cs:102`). v0.107.1 has no such gate: the Before hook
    // runs ahead of Artifact's `ModifyPowerAmountReceived` negation, so an
    // Artifact-eaten debuff captures the trigger there.
    if state.game_version >= crate::GameVersion::V0_111_0 && target_has_artifact(state, ctx.target)
    {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = unsettling_lamp_relic_mut(state) {
        r.counter = UNSETTLING_LAMP_CAPTURED;
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// C# `target.HasPower<ArtifactPower>()` for the lamp's target.
fn target_has_artifact(state: &CombatState, target: crate::hooks::CreatureRef) -> bool {
    // Only an enemy target reaches here (`unsettling_lamp_eligible`).
    let crate::hooks::CreatureRef::Enemy(uid) = target else {
        return false;
    };
    let uid = uid.0;
    state
        .creatures
        .iter()
        .find(|c| c.id == uid)
        .is_some_and(|c| {
            c.powers.iter().any(|p| {
                state
                    .powers
                    .get_by_id(p.0)
                    .is_some_and(|p| p.kind == crate::PowerKind::Artifact)
            })
        })
}

/// `UnsettlingLamp.modify_power_amount_given` — doubling phase. While
/// the relic sits in `CAPTURED`, every eligible debuff applied by the
/// player to an enemy is doubled. Returns `ctx.amount` unchanged when
/// any gate fails (chain-passthrough). Per C# canon
/// `UnsettlingLamp.cs::ModifyPowerAmountGiven`. Bead `sts2-rs-7uo4`.
#[allow(clippy::trivially_copy_pass_by_ref)]
pub(crate) fn on_modify_power_amount_given_unsettling_lamp(
    state: &CombatState,
    ctx: &crate::hooks::PowerAmountCtx,
) -> i32 {
    if !player_owns_relic(state, crate::RelicKind::UnsettlingLamp) {
        return ctx.amount;
    }
    if unsettling_lamp_state(state) != Some(UNSETTLING_LAMP_CAPTURED) {
        return ctx.amount;
    }
    // `ModifyPowerAmountGivenMultiplicative` (UnsettlingLamp.cs:105-122) has
    // no applier check, unlike the capture: once Misery's first copy (a
    // player-applied debuff) captured it, a copy of a monster-applied debuff
    // from the same play is doubled too. The enemy-target gate stays.
    let mut doubling = *ctx;
    doubling.applier = None;
    if !unsettling_lamp_eligible(&doubling) {
        return ctx.amount;
    }
    ctx.amount.saturating_mul(2)
}

